class Solution { private var best:String?=null;fun smallestFromLeaf(root:TreeNode?):String{best=null;dfs(root,StringBuilder());return best!!};private fun dfs(node:TreeNode?,path:StringBuilder){node?:return;path.append(('a'.code+node.`val`).toChar());if(node.left==null&&node.right==null){val candidate=path.reversed().toString();if(best==null||candidate<best!!)best=candidate}else{dfs(node.left,path);dfs(node.right,path)};path.deleteCharAt(path.lastIndex)} }
